import unittest
import unittest.mock as mock
import solution


class TestRetryWithBackoff(unittest.TestCase):
    def test_success_on_first_attempt(self):
        """Test that the function returns immediately on success."""
        fn = mock.Mock(return_value="success")
        result = solution.retry_with_backoff(fn, max_attempts=3)
        self.assertEqual(result, "success")
        fn.assert_called_once()

    def test_success_on_second_attempt(self):
        """Test that the function retries and returns on the second attempt."""
        fn = mock.Mock(side_effect=[Exception("fail"), "success"])
        result = solution.retry_with_backoff(fn, max_attempts=3)
        self.assertEqual(result, "success")
        self.assertEqual(fn.call_count, 2)

    def test_success_on_third_attempt(self):
        """Test that the function retries and returns on the third attempt."""
        fn = mock.Mock(side_effect=[Exception("fail"), Exception("fail"), "success"])
        result = solution.retry_with_backoff(fn, max_attempts=3)
        self.assertEqual(result, "success")
        self.assertEqual(fn.call_count, 3)

    def test_raises_after_max_attempts(self):
        """Test that the function raises the last exception after max_attempts."""
        fn = mock.Mock(side_effect=[Exception("fail1"), Exception("fail2"), Exception("fail3")])
        with self.assertRaises(Exception) as cm:
            solution.retry_with_backoff(fn, max_attempts=3)
        self.assertEqual(fn.call_count, 3)
        self.assertEqual(str(cm.exception), "fail3")

    def test_raises_immediately_if_first_fails_and_max_attempts_is_one(self):
        """Test that the function raises immediately if max_attempts is 1 and it fails."""
        fn = mock.Mock(side_effect=Exception("fail"))
        with self.assertRaises(Exception) as cm:
            solution.retry_with_backoff(fn, max_attempts=1)
        self.assertEqual(fn.call_count, 1)
        self.assertEqual(str(cm.exception), "fail")

    def test_no_sleep_on_success(self):
        """Test that no sleep is called when the function succeeds on the first attempt."""
        fn = mock.Mock(return_value="success")
        with mock.patch('solution.time.sleep') as mock_sleep:
            solution.retry_with_backoff(fn, max_attempts=3)
            mock_sleep.assert_not_called()

    def test_sleeps_on_retries(self):
        """Test that sleep is called with appropriate backoff on retries."""
        fn = mock.Mock(side_effect=[Exception("fail"), "success"])
        with mock.patch('solution.time.sleep') as mock_sleep:
            solution.retry_with_backoff(fn, max_attempts=3)
            mock_sleep.assert_called_once_with(0.01 * 1)

    def test_raises_final_error_without_sleep(self):
        """Test that the final error is raised without an additional sleep."""
        fn = mock.Mock(side_effect=[Exception("fail1"), Exception("fail2"), Exception("fail3")])
        with mock.patch('solution.time.sleep') as mock_sleep:
            with self.assertRaises(Exception):
                solution.retry_with_backoff(fn, max_attempts=3)
            # Should have slept twice (after first and second failures)
            self.assertEqual(mock_sleep.call_count, 2)

