def topological_sort(graph):
    visited = set()
    order = []
    # States: 0 = unvisited, 1 = visiting, 2 = visited
    state = {node: 0 for node in graph}

    def visit(node):
        if state[node] == 1:
            raise ValueError('cycle detected')
        if state[node] == 2:
            return
        state[node] = 1
        for dependency in graph.get(node, []):
            if dependency in state:
                visit(dependency)
        state[node] = 2
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

